const R=[
 {k:'m1',ic:'🧩',c:['Children watch an adult fail at a wire puzzle for a long time,','saying pessimistic things while trying.'],q:'What happened to the children\'s self-efficacy?',o:[['It went down'],['It went up'],['It did not change']],say:`<b>Down.</b> Children who observed a pessimistic model persist for a long time lowered their self-efficacy judgments (Zimmerman &amp; Ringle, 1981).`},
 {k:'m2',ic:'🔤',c:['College students solve anagrams and are told they did better than','a model, or the same. Then they watch the model fail.'],q:'Who kept the higher self-efficacy and persistence?',o:[['Those told they were','more competent'],['Those told they were','equally competent'],['No difference between','the two groups']],say:`<b>Told "more competent".</b> Students who heard they were better than the model kept higher self-efficacy and persisted longer than students who heard they were just as good (Brown &amp; Inouye, 1978).`},
 {k:'m3',ic:'➗',c:['Children learning division get either an adult model who says the','steps while solving, or written instruction.'],q:'What did Schunk (1981) find?',o:[['Both helped; modeling gave higher','achievement, more accurate beliefs'],['Only written','instruction helped'],['Neither had','any effect']],say:`<b>Both helped</b> self-efficacy, persistence and achievement, but modeling led to higher achievement and a more accurate match between self-efficacy and actual performance. A path analysis showed that self-efficacy affected persistence and achievement, and persistence raised achievement.`},
 {k:'m4',ic:'🧒',c:['Children watch a peer mastery model, a peer coping model, an adult','mastery model or no model solving subtraction problems.'],q:'Which models raised self-efficacy and achievement most?',o:[['The peer models','(mastery or coping)'],['The adult','model'],['No model','at all']],say:`<b>Peer models</b> increased self-efficacy and achievement better than the adult model and no model; the adult-model children outperformed the no-model children (Schunk &amp; Hanson, 1985).`},
 {k:'m5',ic:'🍰',c:['Now fractions, a task at which the children had not been','successful before. Peer coping or peer mastery models?'],q:'Which worked better?',o:[['Peer coping','models'],['Peer mastery','models'],['No difference']],say:`<b>Peer coping models</b> enhanced self-efficacy and achievement more than peer mastery models (Schunk, Hanson &amp; Cox, 1987). Coping models may be more effective when students have little task familiarity or previous learning difficulties.`},
 {k:'m6',ic:'👥',c:['Same research: several peer models instead of one.'],q:'How did multiple models do?',o:[['As well as one coping model,','better than one mastery model'],['Worse than one','mastery model'],['Only multiple coping','models helped']],say:`<b>Multiple models</b> (coping or mastery) did as well as one coping model and better than one mastery model: with several models, a learner is likely to find one who resembles her.`},
 {k:'m7',ic:'📹',c:['Children are videotaped solving problems and then watch their','own tapes before practising.'],q:'Compared with taped children who did not watch, and untaped ones?',o:[['Higher self-efficacy, motivation','and strategy use'],['No difference'],['Lower self-efficacy:','they saw their errors']],say:`<b>Self-modeling works</b> (Schunk &amp; Hanson, 1989): higher self-efficacy, motivation and self-regulated strategy use than children who were taped but did not watch, and children who were not taped.`},
 {k:'m8',ic:'✍️',c:['College students learn writing revision. They watch a coping model,','a mastery model or no model; some also get encouragement and feedback.'],q:'What was the order for writing skill and self-efficacy?',o:[['Coping > mastery','> no model'],['Mastery > coping','> no model'],['All models','equal']],say:`<b>Coping &gt; mastery &gt; no model</b> (Zimmerman &amp; Kitsantas, 2002); encouragement and feedback promoted skill and self-efficacy in every condition. The study tested the observation and emulation levels of the social-to-self progression.`}];
